  "claimed_at" TEXT CHECK ("claimed_at" IS NULL OR ("claimed_at" GLOB '????-??-??T??:??:??*+00:00' AND datetime(substr("claimed_at", 1, 19)) IS NOT NULL AND (length("claimed_at") = 25 OR (substr("claimed_at", 20, 1) = '.' AND length("claimed_at") BETWEEN 27 AND 32 AND substr("claimed_at", 21, length("claimed_at") - 26) NOT GLOB '*[^0-9]*')))),
  "started_at" TEXT CHECK ("started_at" IS NULL OR ("started_at" GLOB '????-??-??T??:??:??*+00:00' AND datetime(substr("started_at", 1, 19)) IS NOT NULL AND (length("started_at") = 25 OR (substr("started_at", 20, 1) = '.' AND length("started_at") BETWEEN 27 AND 32 AND substr("started_at", 21, length("started_at") - 26) NOT GLOB '*[^0-9]*')))),
  "finished_at" TEXT CHECK ("finished_at" IS NULL OR ("finished_at" GLOB '????-??-??T??:??:??*+00:00' AND datetime(substr("finished_at", 1, 19)) IS NOT NULL AND (length("finished_at") = 25 OR (substr("finished_at", 20, 1) = '.' AND length("finished_at") BETWEEN 27 AND 32 AND substr("finished_at", 21, length("finished_at") - 26) NOT GLOB '*[^0-9]*')))),
  "created_at" TEXT NOT NULL DEFAULT (rtrim(rtrim(strftime('%Y-%m-%dT%H:%M:%f', 'now'), '0'), '.') || '+00:00') CHECK ("created_at" IS NULL OR ("created_at" GLOB '????-??-??T??:??:??*+00:00' AND datetime(substr("created_at", 1, 19)) IS NOT NULL AND (length("created_at") = 25 OR (substr("created_at", 20, 1) = '.' AND length("created_at") BETWEEN 27 AND 32 AND substr("created_at", 21, length("created_at") - 26) NOT GLOB '*[^0-9]*')))),
  "updated_at" TEXT NOT NULL DEFAULT (rtrim(rtrim(strftime('%Y-%m-%dT%H:%M:%f', 'now'), '0'), '.') || '+00:00') CHECK ("updated_at" IS NULL OR ("updated_at" GLOB '????-??-??T??:??:??*+00:00' AND datetime(substr("updated_at", 1, 19)) IS NOT NULL AND (length("updated_at") = 25 OR (substr("updated_at", 20, 1) = '.' AND length("updated_at") BETWEEN 27 AND 32 AND substr("updated_at", 21, length("updated_at") - 26) NOT GLOB '*[^0-9]*')))),
  "heartbeat_at" TEXT CHECK ("heartbeat_at" IS NULL OR ("heartbeat_at" GLOB '????-??-??T??:??:??*+00:00' AND datetime(substr("heartbeat_at", 1, 19)) IS NOT NULL AND (length("heartbeat_at") = 25 OR (substr("heartbeat_at", 20, 1) = '.' AND length("heartbeat_at") BETWEEN 27 AND 32 AND substr("heartbeat_at", 21, length("heartbeat_at") - 26) NOT GLOB '*[^0-9]*')))),
  "progress" REAL,
