  FOREIGN KEY ("media_asset_id") REFERENCES "media.media_assets" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  FOREIGN KEY ("media_asset_version_id") REFERENCES "media.media_asset_versions" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  FOREIGN KEY ("upload_intent_id") REFERENCES "media.upload_intents" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
